const state = await appStore.getState();
const STORE_KEY = "ledger";

const DEFAULT_CATEGORIES = ["餐饮", "交通", "购物", "居住", "娱乐", "医疗", "工资", "奖金", "理财", "其他"];

function isPlainObject(value) {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function normalizeRecord(raw) {
  const rec = isPlainObject(raw) ? Object.assign({}, raw) : {};
  const type = rec.type === "income" ? "income" : "expense";
  const amountNum = Number(rec.amount);
  return Object.assign(rec, {
    id: typeof rec.id === "string" && rec.id ? rec.id : createId(),
    date: typeof rec.date === "string" ? rec.date : "",
    type: type,
    category: typeof rec.category === "string" ? rec.category : "",
    amount: Number.isFinite(amountNum) ? amountNum : 0,
    note: typeof rec.note === "string" ? rec.note : "",
    createdAt: typeof rec.createdAt === "number" ? rec.createdAt : Date.now()
  });
}

function createId() {
  return "r-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);
}

function loadLedger() {
  const existing = state[STORE_KEY];
  if (!isPlainObject(existing)) {
    return { records: [], categories: DEFAULT_CATEGORIES.slice() };
  }
  const records = Array.isArray(existing.records) ? existing.records.map(normalizeRecord) : [];
  const categories = Array.isArray(existing.categories)
    ? existing.categories.filter(function (c) { return typeof c === "string" && c.trim(); })
    : DEFAULT_CATEGORIES.slice();
  return Object.assign({}, existing, { records: records, categories: categories });
}

let ledger = loadLedger();

async function persist() {
  const next = Object.assign({}, state, { [STORE_KEY]: ledger });
  await appStore.setState(next);
  state[STORE_KEY] = ledger;
}

/* ---------- DOM 引用 ---------- */
const el = {
  monthInput: document.getElementById("monthInput"),
  clearMonthBtn: document.getElementById("clearMonthBtn"),
  sumIncome: document.getElementById("sumIncome"),
  sumExpense: document.getElementById("sumExpense"),
  sumBalance: document.getElementById("sumBalance"),
  form: document.getElementById("entryForm"),
  dateInput: document.getElementById("dateInput"),
  categoryInput: document.getElementById("categoryInput"),
  categoryList: document.getElementById("categoryList"),
  amountInput: document.getElementById("amountInput"),
  noteInput: document.getElementById("noteInput"),
  formError: document.getElementById("formError"),
  submitBtn: document.getElementById("submitBtn"),
  entryList: document.getElementById("entryList"),
  listCount: document.getElementById("listCount"),
  listHint: document.getElementById("listHint"),
  emptyState: document.getElementById("emptyState"),
  confirmBackdrop: document.getElementById("confirmBackdrop"),
  confirmText: document.getElementById("confirmText"),
  confirmOk: document.getElementById("confirmOk"),
  confirmCancel: document.getElementById("confirmCancel")
};

/* ---------- 工具 ---------- */
function pad2(n) {
  return n < 10 ? "0" + n : String(n);
}

function todayISO() {
  const d = new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function currentMonth() {
  return todayISO().slice(0, 7);
}

function formatMoney(n) {
  const abs = Math.abs(n);
  const fixed = abs.toFixed(2);
  const parts = fixed.split(".");
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return (n < 0 ? "-" : "") + "￥" + parts.join(".");
}

function formatDateLabel(iso) {
  if (typeof iso !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso || "未填写日期";
  const parts = iso.split("-");
  return parts[0] + "年" + Number(parts[1]) + "月" + Number(parts[2]) + "日";
}

function showError(message) {
  if (!message) {
    el.formError.hidden = true;
    el.formError.textContent = "";
    return;
  }
  el.formError.hidden = false;
  el.formError.textContent = message;
}

/* ---------- 渲染 ---------- */
function getFilteredRecords() {
  const month = el.monthInput.value;
  const list = ledger.records.slice();
  const filtered = month
    ? list.filter(function (r) { return typeof r.date === "string" && r.date.slice(0, 7) === month; })
    : list;
  filtered.sort(function (a, b) {
    if (a.date === b.date) return (b.createdAt || 0) - (a.createdAt || 0);
    return a.date < b.date ? 1 : -1;
  });
  return filtered;
}

function renderSummary(records) {
  let income = 0;
  let expense = 0;
  records.forEach(function (r) {
    if (r.type === "income") income += r.amount;
    else expense += r.amount;
  });
  el.sumIncome.textContent = formatMoney(income);
  el.sumExpense.textContent = formatMoney(expense);
  el.sumBalance.textContent = formatMoney(income - expense);
}

function renderCategoryOptions() {
  el.categoryList.textContent = "";
  ledger.categories.forEach(function (name) {
    const opt = document.createElement("option");
    opt.value = name;
    el.categoryList.appendChild(opt);
  });
}

function renderList(records) {
  el.entryList.textContent = "";
  el.listCount.textContent = "共 " + records.length + " 条";

  const month = el.monthInput.value;
  el.listHint.textContent = month
    ? "当前筛选：" + month.replace("-", " 年 ") + " 月"
    : "当前显示全部记录";

  if (records.length === 0) {
    el.emptyState.hidden = false;
    el.emptyState.textContent = month
      ? "该月份暂无记录，换个筛选月份或新增一笔吧。"
      : "暂无记录，先在上方添加一笔吧。";
    return;
  }
  el.emptyState.hidden = true;

  records.forEach(function (rec) {
    const li = document.createElement("li");
    li.className = "entry-item " + (rec.type === "income" ? "is-income" : "is-expense");

    const main = document.createElement("div");
    main.className = "entry-main";

    const top = document.createElement("div");
    top.className = "entry-top";

    const cat = document.createElement("span");
    cat.className = "entry-category";
    cat.textContent = rec.category || "未分类";
    top.appendChild(cat);

    const tag = document.createElement("span");
    tag.className = "tag " + (rec.type === "income" ? "tag-income" : "tag-expense");
    tag.textContent = rec.type === "income" ? "收入" : "支出";
    top.appendChild(tag);

    const dateSpan = document.createElement("span");
    dateSpan.className = "entry-date";
    dateSpan.textContent = formatDateLabel(rec.date);
    top.appendChild(dateSpan);

    main.appendChild(top);

    if (rec.note) {
      const note = document.createElement("p");
      note.className = "entry-note";
      note.textContent = rec.note;
      main.appendChild(note);
    }

    const side = document.createElement("div");
    side.className = "entry-side";

    const amount = document.createElement("span");
    amount.className = "entry-amount " + (rec.type === "income" ? "is-income" : "is-expense");
    amount.textContent = (rec.type === "income" ? "+" : "-") + formatMoney(rec.amount);
    side.appendChild(amount);

    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "btn-delete";
    delBtn.textContent = "删除";
    delBtn.addEventListener("click", function () {
      askDelete(rec);
    });
    side.appendChild(delBtn);

    li.appendChild(main);
    li.appendChild(side);
    el.entryList.appendChild(li);
  });
}

function render() {
  const records = getFilteredRecords();
  renderSummary(records);
  renderList(records);
}

/* ---------- 删除确认对话框 ---------- */
let pendingDeleteId = null;

function askDelete(rec) {
  pendingDeleteId = rec.id;
  el.confirmText.textContent =
    "确定要删除「" + (rec.category || "未分类") + " " +
    (rec.type === "income" ? "收入" : "支出") + " " + formatMoney(rec.amount) +
    "（" + formatDateLabel(rec.date) + "）」这条记录吗？此操作不可撤销。";
  el.confirmBackdrop.hidden = false;
  el.confirmOk.focus();
}

function closeConfirm() {
  pendingDeleteId = null;
  el.confirmBackdrop.hidden = true;
}

el.confirmCancel.addEventListener("click", closeConfirm);

el.confirmBackdrop.addEventListener("click", function (event) {
  if (event.target === el.confirmBackdrop) closeConfirm();
});

document.addEventListener("keydown", function (event) {
  if (event.key === "Escape" && !el.confirmBackdrop.hidden) closeConfirm();
});

el.confirmOk.addEventListener("click", async function () {
  const id = pendingDeleteId;
  closeConfirm();
  if (!id) return;
  const before = ledger.records;
  const nextRecords = before.filter(function (r) { return r.id !== id; });
  if (nextRecords.length === before.length) return;
  const prev = ledger;
  ledger = Object.assign({}, ledger, { records: nextRecords });
  render();
  try {
    await persist();
  } catch (err) {
    ledger = prev;
    render();
    showError("删除失败，数据未保存，请重试。");
  }
});

/* ---------- 表单提交 ---------- */
el.form.addEventListener("submit", async function (event) {
  event.preventDefault();
  showError("");

  const date = el.dateInput.value;
  const typeInput = el.form.querySelector('input[name="entryType"]:checked');
  const type = typeInput && typeInput.value === "income" ? "income" : "expense";
  const category = el.categoryInput.value.trim();
  const amountRaw = el.amountInput.value.trim();
  const note = el.noteInput.value.trim();

  if (!date) {
    showError("请选择日期。");
    el.dateInput.focus();
    return;
  }
  if (!category) {
    showError("请填写分类，例如「餐饮」或「工资」。");
    el.categoryInput.focus();
    return;
  }
  if (!amountRaw) {
    showError("请填写金额。");
    el.amountInput.focus();
    return;
  }
  const amount = Number(amountRaw);
  if (!Number.isFinite(amount) || amount <= 0) {
    showError("金额必须是大于 0 的数字。");
    el.amountInput.focus();
    return;
  }
  const rounded = Math.round(amount * 100) / 100;

  const record = {
    id: createId(),
    date: date,
    type: type,
    category: category,
    amount: rounded,
    note: note,
    createdAt: Date.now()
  };

  const categories = ledger.categories.indexOf(category) === -1
    ? ledger.categories.concat([category])
    : ledger.categories.slice();

  const prev = ledger;
  ledger = Object.assign({}, ledger, {
    records: prev.records.concat([record]),
    categories: categories
  });

  renderCategoryOptions();
  render();

  try {
    await persist();
  } catch (err) {
    ledger = prev;
    renderCategoryOptions();
    render();
    showError("保存失败，记录未写入，请重试。");
    return;
  }

  el.amountInput.value = "";
  el.noteInput.value = "";
  el.categoryInput.value = "";
  el.dateInput.value = date;
  el.amountInput.focus();
});

/* ---------- 月份筛选 ---------- */
el.monthInput.addEventListener("change", render);

el.clearMonthBtn.addEventListener("click", function () {
  el.monthInput.value = "";
  render();
});

/* ---------- 初始化 ---------- */
async function init() {
  el.dateInput.value = todayISO();
  el.monthInput.value = currentMonth();
  renderCategoryOptions();
  render();

  if (!isPlainObject(state[STORE_KEY])) {
    try {
      await persist();
    } catch (err) {
      showError("初始化数据失败，本次记录可能无法保存。");
    }
  }
}

await init();

