:root {
  --bg: #0f1b2a;
  --bg-soft: #16263a;
  --panel: #1b2f47;
  --panel-2: #21395a;
  --border: #2c4straight;
  --border: #2c4a6e;
  --text: #e8f1fb;
  --text-dim: #9db3cc;
  --accent: #38bdf8;
  --accent-strong: #0ea5e9;
  --income: #34d399;
  --expense: #fb7185;
  --balance: #fbbf24;
  --danger: #ef4444;
  --radius: 14px;
  --shadow: 0 18px 40px rgba(3, 10, 20, 0.45);
}

#app {
  min-height: 100vh;
  background:
    radial-gradient(1100px 620px at 12% -10%, rgba(56, 189, 248, 0.18), transparent 60%),
    radial-gradient(900px 520px at 100% 0%, rgba(52, 211, 153, 0.14), transparent 55%),
    linear-gradient(180deg, var(--bg) 0%, #0b1522 100%);
  color: var(--text);
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", system-ui, -apple-system, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  box-sizing: border-box;
  padding: 28px 20px 56px;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 1080px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.app-header {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(135deg, rgba(33, 57, 90, 0.95), rgba(20, 36, 58, 0.95));
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px 22px;
  box-shadow: var(--shadow);
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-mark {
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  font-size: 22px;
  font-weight: 700;
  color: #06202f;
  background: linear-gradient(135deg, var(--accent), var(--income));
}

.brand-text h1 {
  margin: 0;
  font-size: 21px;
  letter-spacing: 0.5px;
}

.brand-text p {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--text-dim);
}

.month-filter {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.month-filter label {
  font-size: 13px;
  color: var(--text-dim);
}

.summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.summary-card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  box-shadow: var(--shadow);
  position: relative;
  overflow: hidden;
}

.summary-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
}

.summary-card.income::before { background: var(--income); }
.summary-card.expense::before { background: var(--expense); }
.summary-card.balance::before { background: var(--balance); }

.summary-label {
  font-size: 13px;
  color: var(--text-dim);
}

.summary-value {
  font-size: 24px;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.5px;
}

.summary-card.income .summary-value { color: var(--income); }
.summary-card.expense .summary-value { color: var(--expense); }
.summary-card.balance .summary-value { color: var(--balance); }

.layout {
  display: grid;
  grid-template-columns: minmax(0, 360px) minmax(0, 1fr);
  gap: 20px;
  align-items: start;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: var(--shadow);
}

.panel h2 {
  margin: 0 0 16px;
  font-size: 17px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}

.field label,
.field-label {
  font-size: 13px;
  color: var(--text-dim);
}

input[type="text"],
input[type="number"],
input[type="date"],
input[type="month"],
textarea,
select {
  width: 100%;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--bg-soft);
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

textarea {
  resize: vertical;
  min-height: 62px;
}

input::placeholder,
textarea::placeholder {
  color: #6f88a5;
}

input:focus,
textarea:focus,
select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.22);
}

input[type="date"],
input[type="month"] {
  color-scheme: dark;
}

.type-switch {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.type-option {
  position: relative;
  display: block;
}

.type-option input {
  position: absolute;
  opacity: 0;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  cursor: pointer;
}

.type-option span {
  display: block;
  text-align: center;
  padding: 9px 0;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--bg-soft);
  color: var(--text-dim);
  font-size: 14px;
  transition: all 0.15s ease;
}

.type-option input:checked + span {
  color: #06202f;
  font-weight: 600;
  border-color: transparent;
}

.type-option input[value="income"]:checked + span {
  background: var(--income);
}

.type-option input[value="expense"]:checked + span {
  background: var(--expense);
}

.type-option input:focus-visible + span {
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.35);
}

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 10px 16px;
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
  transition: transform 0.12s ease, filter 0.15s ease, background 0.15s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  width: 100%;
  background: linear-gradient(135deg, var(--accent), var(--accent-strong));
  color: #04202f;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.btn-primary:hover {
  filter: brightness(1.08);
}

.btn-ghost {
  background: transparent;
  border-color: var(--border);
  color: var(--text-dim);
}

.btn-ghost:hover {
  color: var(--text);
  border-color: var(--accent);
}

.btn-danger {
  background: var(--danger);
  color: #fff;
  font-weight: 600;
}

.btn-danger:hover {
  filter: brightness(1.08);
}

.form-error {
  margin: 0 0 12px;
  padding: 9px 12px;
  border-radius: 10px;
  background: rgba(239, 68, 68, 0.16);
  border: 1px solid rgba(239, 68, 68, 0.5);
  color: #fecaca;
  font-size: 13px;
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.list-head h2 {
  margin-bottom: 0;
}

.list-count {
  font-size: 13px;
  color: var(--text-dim);
}

.list-hint {
  margin: 8px 0 0;
  font-size: 12.5px;
  color: var(--text-dim);
}

.entry-list {
  list-style: none;
  margin: 14px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 560px;
  overflow-y: auto;
}

.entry-item {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  align-items: center;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-left: 4px solid var(--border);
  border-radius: 12px;
  padding: 12px 14px;
}

.entry-item.is-income {
  border-left-color: var(--income);
}

.entry-item.is-expense {
  border-left-color: var(--expense);
}

.entry-main {
  min-width: 0;
}

.entry-top {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.entry-category {
  font-weight: 600;
  font-size: 15px;
  word-break: break-word;
}

.tag {
  font-size: 11.5px;
  padding: 1px 8px;
  border-radius: 999px;
  border: 1px solid transparent;
}

.tag-income {
  color: var(--income);
  background: rgba(52, 211, 153, 0.14);
  border-color: rgba(52, 211, 153, 0.4);
}

.tag-expense {
  color: var(--expense);
  background: rgba(251, 113, 133, 0.14);
  border-color: rgba(251, 113, 133, 0.4);
}

.entry-date {
  font-size: 12.5px;
  color: var(--text-dim);
  font-variant-numeric: tabular-nums;
}

.entry-note {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--text-dim);
  word-break: break-word;
  white-space: pre-wrap;
}

.entry-side {
  display: flex;
  align-items: center;
  gap: 12px;
}

.entry-amount {
  font-size: 16px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.entry-amount.is-income { color: var(--income); }
.entry-amount.is-expense { color: var(--expense); }

.btn-delete {
  background: transparent;
  border: 1px solid rgba(239, 68, 68, 0.5);
  color: #fca5a5;
  border-radius: 9px;
  padding: 6px 11px;
  font-size: 13px;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s ease, color 0.15s ease;
}

.btn-delete:hover {
  background: rgba(239, 68, 68, 0.18);
  color: #fff;
}

.empty-state {
  margin: 18px 0 4px;
  padding: 26px 16px;
  text-align: center;
  color: var(--text-dim);
  font-size: 14px;
  border: 1px dashed var(--border);
  border-radius: 12px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(4, 10, 18, 0.68);
  display: grid;
  place-items: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: min(400px, 100%);
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  box-shadow: var(--shadow);
}

.dialog h3 {
  margin: 0 0 10px;
  font-size: 17px;
}

.dialog p {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text-dim);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 860px) {
  .layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .summary {
    grid-template-columns: minmax(0, 1fr);
  }
  #app {
    padding: 18px 14px 40px;
  }
}
